mapper.sql:
WHERE u.valid = 1

    AND u.user_id = #{query.userId}


    AND u.mobile LIKE CONCAT('%', #{query.mobile}, '%')


    AND u.email LIKE CONCAT('%', #{query.email}, '%')


    AND u.username LIKE CONCAT('%', #{query.username}, '%')


    AND u.name LIKE CONCAT('%', #{query.name}, '%')


    AND ui.avatar_url LIKE CONCAT('%', #{query.avatarUrl}, '%')


    AND ui.job_number LIKE CONCAT('%', #{query.jobNumber}, '%')


    AND u.status = #{query.status}


    AND u.ctime  >=  #{query.createdStartTime}


    AND u.ctime  <=  #{query.createdEndTime}
